class Solution {
public:
    int minimumSubstringsInPartition(string s) {
        int n = s.size();
        vector<int> dp(n + 1, 1e9);
        dp[0] = 0;

        for (int i = 1; i <= n; ++i) {
            vector<int> counts(26, 0);
            int distinct = 0, max_f = 0;
            for (int j = i; j >= 1; --j) {
                int c = s[j - 1] - 'a';
                if (counts[c] == 0) distinct++;
                counts[c]++;
                max_f = max(max_f, counts[c]);

                if ((i - j + 1) == distinct * max_f) {
                    dp[i] = min(dp[i], dp[j - 1] + 1);
                }
            }
        }
        return dp[n];
    }
};

class Solution {
    public int minimumSubstringsInPartition(String s) {
        int n = s.length();
        int[] dp = new int[n + 1];
        Arrays.fill(dp, 1_000_000_000);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            int[] counts = new int[26];
            int distinct = 0, maxF = 0;
            for (int j = i; j >= 1; j--) {
                int c = s.charAt(j - 1) - 'a';
                if (counts[c] == 0) distinct++;
                counts[c]++;
                maxF = Math.max(maxF, counts[c]);

                if ((i - j + 1) == distinct * maxF) {
                    dp[i] = Math.min(dp[i], dp[j - 1] + 1);
                }
            }
        }
        return dp[n];
    }
}

var minimumSubstringsInPartition = function(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;

    for (let i = 1; i <= n; i++) {
        const counts = new Array(26).fill(0);
        let distinct = 0, maxF = 0;
        for (let j = i; j >= 1; j--) {
            const c = s.charCodeAt(j - 1) - 97;
            if (counts[c] === 0) distinct++;
            counts[c]++;
            if (counts[c] > maxF) maxF = counts[c];

            if ((i - j + 1) === distinct * maxF) {
                dp[i] = Math.min(dp[i], dp[j - 1] + 1);
            }
        }
    }
    return dp[n];
};
